"""Inert measurement-only fixture, never production code."""
SOURCE = 'using System.Diagnostics;\nusing System.Numerics;\nusing System.Text.Json;\nusing Silk.NET.Vulkan;\nusing Tertius.Assets;\nusing Tertius.Demo;\nusing Tertius.Host.Scripting;\nusing Tertius.Rendering;\nusing Tertius.Simulation;\nusing static Tertius.Host.Tests.HostTesting;\n\nnamespace Tertius.Host.Tests;\n\n/// <summary>Pristine timing proposal. One observed presentation per cut. Prior diagnostic censoring stays separate.</summary>\n[Collection(MeasurementCollection.Name)]\npublic sealed class LinuxExposureMeasurements\n{\n    private static readonly List<object> Rows = [];\n    private static bool Fsr = Environment.GetEnvironmentVariable("TERTIUS_LINUX_FSR") == "1";\n    private static bool Steady = Environment.GetEnvironmentVariable("TERTIUS_LINUX_LANE") == "steady";\n    private static readonly bool Validate = Environment.GetEnvironmentVariable("TERTIUS_LINUX_VALIDATE") == "1";\n    private static string Folder = Environment.GetEnvironmentVariable("TERTIUS_LINUX_OUT")\n        ?? throw new InvalidOperationException("Set TERTIUS_LINUX_OUT.");\n    private static readonly bool SmokeFilm = Environment.GetEnvironmentVariable("TERTIUS_LINUX_SMOKE") == "film";\n    private static readonly bool Smoke = Environment.GetEnvironmentVariable("TERTIUS_LINUX_SMOKE") is "1" or "film";\n    private static readonly bool Batch = Environment.GetEnvironmentVariable("TERTIUS_LINUX_BATCH") == "1";\n    private static readonly bool Diagnostic = Environment.GetEnvironmentVariable("TERTIUS_LINUX_DIAGNOSTIC") == "1";\n    private static readonly Dictionary<string, Sample> References = [];\n    private const int RecoveryFrames = 0;\n    private const float StopTolerance = 1f / 16;\n    private const int PixelTolerance = 2;\n\n    [Fact(Explicit = true)]\n    public void ReportWholeCutLatencyAndOrdinaryFrameCosts()\n    {\n        string originalFolder = Folder;\n        string[] modes = Batch ? ["native", "fsr"] : [Fsr ? "fsr" : "native"];\n        string[] lanes = Batch ? ["cut", "steady"] : [Steady ? "steady" : "cut"];\n        foreach (string mode in modes)\n        foreach (string lane in lanes)\n        {\n            Fsr = mode == "fsr";\n            Steady = lane == "steady";\n            Folder = Batch ? Path.Combine(originalFolder, mode, lane) : originalFolder;\n            Rows.Clear();\n            RunLane();\n        }\n    }\n\n    private static void RunLane()\n    {\n        Directory.CreateDirectory(Folder);\n        Console.Error.WriteLine($"LINUX_LANE {(Fsr ? "fsr" : "native")} {(Steady ? "steady" : "cut")}");\n        try\n        {\n            if (Smoke)\n            {\n                if (Steady)\n                {\n                    OrdinarySmoke();\n                    return;\n                }\n                if (SmokeFilm)\n                    Case("real-outside", () => RealCut("outside", 1417));\n                else\n                    Case("synthetic-extreme", () => Synthetic(source: 1361, destination: 1e-12f, compensation: -13, control: "cut"));\n                return;\n            }\n            if (Steady)\n            {\n                Case("steady", RealSteady);\n                return;\n            }\n            Case("real-outside", () => RealCut("outside", 1417));\n            Case("real-return", () => RealCut("return", 1462));\n        }\n        finally\n        {\n            File.WriteAllText(Path.Combine(Folder, "rows.json"), JsonSerializer.Serialize(new\n            {\n                Fsr, Steady, Validate, Smoke, Diagnostic, Stopwatch.Frequency, RecoveryFrames, StopTolerance, PixelTolerance,\n                MeterBins = ExposureMeter.Bins,\n                ObservationBytesPerPresentation = Steady ? 0 : 8,\n                Rows,\n            }, new JsonSerializerOptions { WriteIndented = true }));\n        }\n    }\n\n    private static void Case(string label, Action run)\n    {\n        long start = Stopwatch.GetTimestamp();\n        run();\n        Rows.Add(new { Kind = "case-duration", Label = label,\n            Seconds = (Stopwatch.GetTimestamp() - start) / (double)Stopwatch.Frequency });\n    }\n\n    private static void OrdinarySmoke()\n    {\n        using VulkanRenderer renderer = Renderer(Options(true, AutoExposure.Default), out Boundary boundary);\n        RenderSnapshot snapshot = Ramp(renderer, 3);\n        for (int i = 0; i < 4; i++)\n        {\n            snapshot.Time = i / 60.0;\n            Sample frame = Draw(renderer, boundary, snapshot, capture: false);\n            if (i > 0 && (frame.Draws != 1 || frame.Presentations != 1 || frame.CaptureRequested))\n                throw new InvalidOperationException("Ordinary smoke requested capture or repeated rendering.");\n            Rows.Add(new { Kind = "ordinary-smoke", Index = i, Frame = frame });\n        }\n        Clean(renderer);\n    }\n\n    private static RendererOptions Options(bool synthetic, ExposureSetting exposure) => new()\n    {\n        Width = synthetic ? 160 : 1280,\n        Height = synthetic ? 90 : 720,\n        Validation = Validate,\n        FramesInFlight = 1,\n        CapturesInFlight = false,\n        WarmUpFrames = 0,\n        Exposure = exposure,\n        Upscaling = Fsr ? new Fsr3Upscaling(new FixedRenderScale(2f / 3), 0) : new NoUpscaling(),\n        OutputDither = false,\n        PassTimestamps = true,\n    };\n\n    private static VulkanRenderer Renderer(RendererOptions options, out Boundary boundary)\n    {\n        Boundary? made = null;\n        VulkanRenderer renderer = VulkanRenderer.CreateOffscreen(\n            options: options,\n            createOutput: (device, allocator, extent) => made = new(\n                device, allocator, new HeadlessTarget(device: device, allocator: allocator, extent: extent, bgra: false)),\n            headless: true);\n        boundary = made ?? throw new InvalidOperationException("No output target.");\n        boundary.ExposureBuffer = () => renderer.Exposure.Buffer;\n        Rows.Add(new { Kind = "options", renderer.DeviceName, Options = options });\n        return renderer;\n    }\n\n    private static void RealCut(string destination, int expectedTick)\n    {\n        Sample reference = RealReference(destination);\n        using VulkanRenderer renderer = Renderer(Options(false, AutoExposure.Default), out Boundary boundary);\n        using World world = WorldTesting.NewWorld(backend: out _, debugChecks: false);\n        Script script = FilmScript();\n        SceneInstance scene = DemoScenes.For(ContentFolders.Find()).Single(s => s.Name == script.Scene).Build(world, renderer);\n        var playback = new Playback(renderer, boundary);\n        bool requested = false;\n        string destinationCamera = destination == "outside" ? "cockpit-outside-camera" : "pen-camera";\n        foreach (ScriptStep step in script.Steps)\n        {\n            if (step is CameraStep camera && camera.Entity == destinationCamera)\n            {\n                playback.RequestedAt = Stopwatch.GetTimestamp();\n                playback.RequestDraws = renderer.DrawnFrames;\n                playback.RequestPresentations = boundary.Records.Count;\n                requested = true;\n                playback.StopAt = destination + "-000000";\n            }\n            ScriptRunner.Run(script: script with { Steps = new[] { step } }, world: world, scene: scene, playback: playback);\n            if (requested && playback.Snapshot != null && playback.Name == playback.StopAt)\n                break;\n        }\n        if (world.TickNumber != expectedTick || playback.Last is null || playback.Snapshot is null)\n            throw new InvalidOperationException($"{destination}: expected tick {expectedTick}, got {world.TickNumber}.");\n        ReportRecovery(\n            renderer: renderer, boundary: boundary, snapshot: playback.Snapshot,\n            first: playback.Last, reference: reference, request: playback.RequestedAt,\n            drawStart: playback.RequestDraws, presentationStart: playback.RequestPresentations,\n            label: "film-" + destination, tick: expectedTick);\n        Clean(renderer);\n    }\n\n    private static Script FilmScript() => Script.Load(Path.Combine(\n        Environment.GetEnvironmentVariable("TERTIUS_LINUX_SCRIPTS") ?? throw new InvalidOperationException("No scripts."),\n        "issue4-cut-first-present.json"));\n\n    private static Sample RealReference(string destination)\n    {\n        using VulkanRenderer renderer = Renderer(Options(false, AutoExposure.Default), out Boundary boundary);\n        using World world = WorldTesting.NewWorld(backend: out _, debugChecks: false);\n        string path = Path.Combine(Environment.GetEnvironmentVariable("TERTIUS_LINUX_SCRIPTS")!,\n            destination == "outside" ? "issue4-cut-outside-control.json" : "issue4-cut-return-control.json");\n        Script script = Script.Load(path);\n        SceneInstance scene = DemoScenes.For(ContentFolders.Find()).Single(s => s.Name == script.Scene).Build(world, renderer);\n        var playback = new Playback(renderer, boundary);\n        ScriptRunner.Run(script: script, world: world, scene: scene, playback: playback);\n        RenderSnapshot snapshot = playback.Snapshot ?? throw new InvalidOperationException("No cold snapshot.");\n        Sample? previous = null;\n        Sample last = playback.Last ?? throw new InvalidOperationException("No cold frame.");\n        for (int i = 0; i < 8; i++)\n        {\n            previous = last;\n            last = Draw(renderer, boundary, snapshot, capture: true);\n        }\n        bool settled = Correct(last, previous!);\n        Rows.Add(new { Kind = "cold-reference", Label = "film-" + destination, world.TickNumber,\n            Frames = 9, Settled = settled, Last = last, Previous = previous, Draws = renderer.DrawnFrames });\n        if (!settled)\n            throw new InvalidOperationException("The independent cold reference did not settle.");\n        Clean(renderer);\n        return last;\n    }\n\n    private static void RealSteady()\n    {\n        using VulkanRenderer renderer = Renderer(Options(false, AutoExposure.Default), out Boundary boundary);\n        using World world = WorldTesting.NewWorld(backend: out _, debugChecks: false);\n        Script script = FilmScript();\n        SceneInstance scene = DemoScenes.For(ContentFolders.Find()).Single(s => s.Name == script.Scene).Build(world, renderer);\n        var playback = new Playback(renderer, boundary) { CapturePixels = false };\n        foreach (ScriptStep step in script.Steps)\n        {\n            if (step is FilmStep)\n                break;\n            ScriptRunner.Run(script: script with { Steps = new[] { step } }, world: world, scene: scene, playback: playback);\n        }\n        // Continue actual world ticks, at one film frame per tick. No cuts, captures or PNG work in this lane.\n        for (int i = 0; i < 120; i++)\n        {\n            world.Tick();\n            playback.Capture(world, "steady");\n            Rows.Add(new { Kind = "steady", Index = i, Measured = i >= 24, world.TickNumber,\n                Frame = playback.Last, Draws = renderer.DrawnFrames });\n        }\n        Clean(renderer);\n    }\n\n    private static void Synthetic(float source, float destination, float compensation, string control)\n    {\n        ExposureSetting exposure = control == "fixed" ? new FixedExposure(-2)\n            : AutoExposure.Default with { CompensationStops = compensation };\n        string referenceKey = $"{Fsr}/{destination:R}/{compensation:R}/{control == "fixed"}";\n        Sample reference;\n        if (References.TryGetValue(referenceKey, out Sample? cached))\n        {\n            reference = cached;\n            Rows.Add(new { Kind = "cold-reference-reuse", referenceKey, Last = reference });\n        }\n        else\n        {\n        using (VulkanRenderer cold = Renderer(Options(true, exposure), out Boundary coldBoundary))\n        {\n            RenderSnapshot coldSnapshot = Ramp(cold, destination);\n            Sample? previous = null;\n            Sample last = Draw(cold, coldBoundary, coldSnapshot, capture: true);\n            int referenceCaptures = destination < 1e-10f ? 64 : 8;\n            for (int i = 0; i < referenceCaptures; i++)\n            {\n                previous = last;\n                last = Draw(cold, coldBoundary, coldSnapshot, capture: true);\n            }\n            if (!Correct(last, previous!))\n                throw new InvalidOperationException("The synthetic cold reference did not settle.");\n            Rows.Add(new { Kind = "cold-reference", Label = "synthetic", source, destination, compensation, control,\n                Frames = referenceCaptures + 1, Last = last, Previous = previous, Draws = cold.DrawnFrames });\n            reference = last;\n            References.Add(referenceKey, reference);\n            Clean(cold);\n        }\n        }\n        using VulkanRenderer renderer = Renderer(Options(true, exposure), out Boundary boundary);\n        RenderSnapshot snapshot = Ramp(renderer, source);\n        for (int i = 0; i < 8; i++)\n            Draw(renderer, boundary, snapshot, capture: true);\n        long draws = renderer.DrawnFrames;\n        int presentations = boundary.Records.Count;\n        long request = Stopwatch.GetTimestamp();\n        SetStar(snapshot, destination);\n        if (control != "continuous")\n            snapshot.CameraCuts++;\n        else\n            TestChains.Of(snapshot, (8, Quaternion.Identity));\n        snapshot.Time = 1.0 / 60;\n        Sample first = Draw(renderer, boundary, snapshot, capture: true);\n        ReportRecovery(\n            renderer: renderer, boundary: boundary, snapshot: snapshot, first: first, reference: reference,\n            request: request, drawStart: draws, presentationStart: presentations,\n            label: $"synthetic-{control}-{source:R}-{destination:R}-comp{compensation:R}", tick: -1);\n        Clean(renderer);\n    }\n\n    private static void ReportRecovery(\n        VulkanRenderer renderer, Boundary boundary, RenderSnapshot snapshot, Sample first, Sample reference,\n        long request, long drawStart, int presentationStart, string label, int tick)\n    {\n        var samples = new List<object>();\n        Sample current = first;\n        double? correctMilliseconds = null;\n        long? correctDraws = null;\n        int? correctPresentations = null;\n        BoundaryRecord firstPresentation = boundary.Records[presentationStart];\n        bool firstCorrect = Correct(first, reference);\n        for (int i = 0; i <= RecoveryFrames; i++)\n        {\n            BoundaryRecord? correctPresentation = boundary.Records.Skip(presentationStart)\n                .FirstOrDefault(record => Correct(record, reference));\n            bool correct = correctPresentation != null;\n            samples.Add(new { Index = i, Correct = correct, Frame = current });\n            if (correctPresentation != null)\n            {\n                int index = boundary.Records.IndexOf(correctPresentation) - presentationStart;\n                correctMilliseconds = Milliseconds(correctPresentation.CompletedAt - request);\n                correctDraws = index + 1;\n                correctPresentations = index + 1;\n                break;\n            }\n            if (i == RecoveryFrames)\n                break;\n            // Freeze the first destination pose, but continue its film clock by 1/60 s per presentation.\n            snapshot.Time += 1.0 / 60;\n            current = Draw(renderer, boundary, snapshot, capture: true);\n        }\n        Rows.Add(new { Kind = "cut", Label = label, Tick = tick, RequestAt = request,\n            FirstPresentationMilliseconds = Milliseconds(firstPresentation.CompletedAt - request),\n            FirstEnqueueMilliseconds = Milliseconds(firstPresentation.SubmittedAt - request),\n            FirstApiReturnMilliseconds = Milliseconds(first.EndAt - request),\n            FirstApiCorrect = firstCorrect,\n            FirstPresentationCorrect = Correct(firstPresentation, reference),\n            CorrectMilliseconds = correctMilliseconds,\n            CorrectDraws = correctDraws, CorrectPresentations = correctPresentations,\n            RightCensored = correctMilliseconds is null,\n            FollowupFramesObserved = samples.Count - 1,\n            CorrectFollowupFrames = correctMilliseconds is null ? (int?)null : samples.Count - 1,\n            CorrectSnapshotSeconds = correctMilliseconds is null ? (double?)null : (samples.Count - 1) / 60.0,\n            TotalShadingDrawsFirstApi = first.Draws, TotalShadingDrawsObserved = renderer.DrawnFrames - drawStart,\n            FirstApiPresentations = first.Presentations,\n            ExactFirstPresentationAttribution = true,\n            Reference = reference, Frames = samples,\n            Presentations = boundary.Records.Skip(presentationStart).ToArray() });\n    }\n\n    private static bool Correct(Sample actual, Sample reference) =>\n        actual.Center.Length == 3 && reference.Center.Length == 3\n        && actual.Stops is float stops && reference.Stops is float expected\n        && Math.Abs(stops - expected) <= StopTolerance\n        && actual.Center.Zip(reference.Center).All(pair => Math.Abs(pair.First - pair.Second) <= PixelTolerance);\n\n    private static bool Correct(BoundaryRecord actual, Sample reference) =>\n        actual.Center.Length == 3 && reference.Center.Length == 3\n        && actual.AppliedStops is float stops && reference.Stops is float expected\n        && Math.Abs(stops - expected) <= StopTolerance\n        && actual.Center.Zip(reference.Center).All(pair => Math.Abs(pair.First - pair.Second) <= PixelTolerance);\n\n    private static Sample Draw(VulkanRenderer renderer, Boundary boundary, RenderSnapshot snapshot, bool capture)\n    {\n        long draws = renderer.DrawnFrames;\n        int presentations = boundary.Records.Count;\n        var sink = new PixelSink();\n        if (capture)\n            renderer.CaptureNextFrame(sink);\n        long start = Stopwatch.GetTimestamp();\n        renderer.Render(snapshot, 1f);\n        long end = Stopwatch.GetTimestamp();\n        GpuTimings? timings = renderer.LastFrameStats.GpuTimings;\n        if (renderer.DrawnFrames - draws != boundary.Records.Count - presentations)\n            throw new InvalidOperationException("Draw and presentation totals disagree.");\n        if (Smoke && presentations == 0 && boundary.Records.Count - presentations > 1)\n            Rows.Add(new { Kind = "multiple-presentation-smoke", Draws = renderer.DrawnFrames - draws,\n                Presentations = boundary.Records.Skip(presentations).ToArray(),\n                FinalCaptureStops = renderer.LastFrameStats.Exposure?.Stops, FinalCaptureCenter = sink.Center });\n        if (capture)\n        {\n            BoundaryRecord shown = boundary.Records[^1];\n            float? reported = renderer.LastFrameStats.Exposure?.Stops;\n            if (reported != shown.AppliedStops || !sink.Center.SequenceEqual(shown.Center))\n                throw new InvalidOperationException("Per-presentation observation differs from the final capture.");\n        }\n        return new Sample(start, end, renderer.DrawnFrames - draws, boundary.Records.Count - presentations,\n            renderer.LastFrameStats.Exposure?.Stops, sink.Center,\n            timings?.Frame, timings?.SpanMilliseconds, timings?.Passes.ToArray() ?? [], capture)\n        {\n            ActiveSize = [(int)renderer.LastScene.Constants.Viewport.X, (int)renderer.LastScene.Constants.Viewport.Y],\n            OutputSize = [(int)renderer.LastScene.Constants.OutputViewport.X, (int)renderer.LastScene.Constants.OutputViewport.Y],\n        };\n    }\n\n    private static RenderSnapshot Ramp(VulkanRenderer renderer, float irradiance)\n    {\n        var snapshot = new RenderSnapshot\n        {\n            Camera = new() { Rotation = Quaternion.Identity, PreviousRotation = Quaternion.Identity, VerticalFov = MathF.PI / 3 },\n            CameraCuts = 1,\n            Ambient = new() { Intensity = 0 },\n        };\n        TestChains.Of(snapshot, (7, Quaternion.Identity));\n        const int width = 256;\n        byte[] pixels = new byte[width * 4 * 4];\n        for (int x = 0; x < width; x++)\n        {\n            double linear = 0.9 * Math.Pow(2, -8 * (x + 0.5) / width);\n            double srgb = linear <= 0.0031308 ? 12.92 * linear : 1.055 * Math.Pow(linear, 1 / 2.4) - 0.055;\n            byte value = (byte)Math.Round(srgb * 255);\n            for (int y = 0; y < 4; y++)\n            {\n                int index = (y * width + x) * 4;\n                pixels[index] = value;\n                pixels[index + 1] = value;\n                pixels[index + 2] = value;\n                pixels[index + 3] = 255;\n            }\n        }\n        MaterialId material = renderer.CreateMaterial(new(BaseColor: Vector4.One, Roughness: 1, Reflectance: 0,\n            BaseColorMap: renderer.CreateTexture(new TextureData(Width: width, Height: 4, Rgba: pixels))));\n        snapshot.Instances.Add(RenderInstance.Create(\n            mesh: renderer.CreateMesh(Primitives.Plane(5)), material: material, position: new(0, 0, -3),\n            rotation: Quaternion.CreateFromAxisAngle(Vector3.UnitX, MathF.PI / 2), scale: Vector3.One,\n            boundingRadius: 0, hemisphere: HemisphereUp.Along(Vector3.UnitY), chainDepth: TestChains.CamerasFrame,\n            flags: RenderFlags.Visible, entityIndex: 0, part: 0));\n        SetStar(snapshot, irradiance);\n        return snapshot;\n    }\n\n    private static void SetStar(RenderSnapshot snapshot, float irradiance)\n    {\n        const double distance = 1.5e11;\n        Vector3 position = Vector3.UnitZ * (float)distance;\n        snapshot.Lights.Clear();\n        snapshot.Lights.Add(new PointRenderLight(\n            EntityIndex: 1_000_000, EntityGeneration: 0, Position: position, PreviousPosition: position,\n            Color: new(1f, 0.96f, 0.9f), Power: (float)(4 * Math.PI * distance * distance * irradiance),\n            Radius: (float)(distance * Math.Sin(0.00467)), CastsShadow: true, ChainDepth: TestChains.Root));\n    }\n\n    private static double Milliseconds(long ticks) => ticks * 1000.0 / Stopwatch.Frequency;\n\n    private static void Clean(VulkanRenderer renderer)\n    {\n        string[] messages = renderer.ValidationMessages.ToArray();\n        Rows.Add(new { Kind = "validation", Messages = messages });\n        if (messages.Length > 0)\n            throw new InvalidOperationException("Vulkan validation emitted messages.");\n    }\n\n    private sealed record Sample(long StartAt, long EndAt, long Draws, int Presentations,\n        float? Stops, int[] Center, long? GpuFrame, double? GpuMilliseconds, PassTiming[] Passes, bool CaptureRequested)\n    {\n        public int[] ActiveSize { get; init; } = [];\n        public int[] OutputSize { get; init; } = [];\n    }\n    private sealed record BoundaryRecord(long SubmittedAt, long CompletedAt, float? AppliedStops, int[] Center);\n\n    private sealed class Playback(VulkanRenderer renderer, Boundary boundary) : IPlayback\n    {\n        public string? StopAt { get; set; }\n        public string? Name { get; private set; }\n        public bool CapturePixels { get; init; } = true;\n        public long RequestedAt { get; set; }\n        public long RequestDraws { get; set; }\n        public int RequestPresentations { get; set; }\n        public Sample? Last { get; private set; }\n        public RenderSnapshot? Snapshot { get; private set; }\n        public bool WaitForTick() => true;\n        public bool Capture(World world, string name)\n        {\n            world.PublishRenderSnapshot();\n            Snapshot = world.RenderSnapshots.AcquireLatest() ?? world.RenderSnapshots.ReadBuffer;\n            Last = Draw(renderer, boundary, Snapshot, CapturePixels);\n            Name = name;\n            return name != StopAt;\n        }\n    }\n\n    private sealed class PixelSink : ICaptureSink\n    {\n        public int[] Center { get; private set; } = [];\n        public void Take(in CapturedImage image)\n        {\n            int center = 4 * (image.Height / 2 * image.Width + image.Width / 2);\n            Center = new[] { (int)image.Rgba[center], (int)image.Rgba[center + 1], (int)image.Rgba[center + 2] };\n        }\n    }\n\n    // A completed offscreen Vulkan submission is the presentation boundary. It does not include compositor/vblank latency.\n    private sealed class Boundary(VulkanDevice device, DeviceAllocator allocator, HeadlessTarget target) : IOutputTarget\n    {\n        private readonly GpuBuffer? observation = Steady ? null : GpuBuffer.Create(\n            device: device, allocator: allocator, size: 8, usage: BufferUsageFlags.TransferDstBit,\n            memoryUsage: MemoryUsage.Readback, name: "measurement presentation observation");\n        private GpuImage? acquired;\n        public Func<GpuBuffer>? ExposureBuffer { get; set; }\n        public List<BoundaryRecord> Records { get; } = [];\n        public Format Format => target.Format;\n        public Extent2D Extent => target.Extent;\n        public bool EncodeSrgbInShader => target.EncodeSrgbInShader;\n        public bool BgraOrder => target.BgraOrder;\n        public bool CanCapture => target.CanCapture;\n        public GpuImage? Acquire(FrameResources frame) => acquired = target.Acquire(frame);\n        public unsafe void FinishRecording(BarrierBatch barriers, CommandBuffer commandBuffer)\n        {\n            target.FinishRecording(barriers, commandBuffer);\n            if (observation is null)\n                return;\n            GpuImage image = acquired ?? throw new InvalidOperationException("No acquired output.");\n            GpuBuffer exposure = ExposureBuffer?.Invoke() ?? throw new InvalidOperationException("No exposure buffer.");\n            barriers.Image(image, ImageUse.TransferSource);\n            barriers.Buffer(exposure, BufferUse.TransferSource);\n            barriers.Buffer(observation, BufferUse.TransferDestination);\n            barriers.Flush(device.Vk, commandBuffer);\n            var pixel = new BufferImageCopy\n            {\n                BufferOffset = 4,\n                ImageSubresource = new(aspectMask: ImageAspectFlags.ColorBit, mipLevel: 0, baseArrayLayer: 0, layerCount: 1),\n                ImageOffset = new((int)Extent.Width / 2, (int)Extent.Height / 2, 0),\n                ImageExtent = new(1, 1, 1),\n            };\n            device.Vk.CmdCopyImageToBuffer(commandBuffer: commandBuffer, srcImage: image.Handle,\n                srcImageLayout: ImageLayout.TransferSrcOptimal, dstBuffer: observation.Handle,\n                regionCount: 1, pRegions: &pixel);\n            var applied = new BufferCopy(srcOffset: 4, dstOffset: 0, size: 4);\n            device.Vk.CmdCopyBuffer(commandBuffer: commandBuffer, srcBuffer: exposure.Handle,\n                dstBuffer: observation.Handle, regionCount: 1, pRegions: &applied);\n            barriers.Buffer(observation, BufferUse.HostRead);\n            barriers.Flush(device.Vk, commandBuffer);\n        }\n        public unsafe void SubmitAndPresent(FrameResources frame)\n        {\n            target.SubmitAndPresent(frame);\n            long submitted = Stopwatch.GetTimestamp();\n            Fence fence = frame.Fence;\n            device.Vk.WaitForFences(device.Device, 1, &fence, true, ulong.MaxValue).Check("linux presentation fence");\n            long completed = Stopwatch.GetTimestamp();\n            float? applied = observation is null ? null : *(float*)observation.Mapped;\n            int[] center = observation is null ? [] : new[] {\n                (int)((byte*)observation.Mapped)[4], (int)((byte*)observation.Mapped)[5], (int)((byte*)observation.Mapped)[6] };\n            Records.Add(new(submitted, completed, applied, center));\n        }\n        public void Resize(Extent2D extent) => target.Resize(extent);\n        public void Dispose()\n        {\n            observation?.Dispose();\n            target.Dispose();\n        }\n    }\n}\n'
